/** The candidate questions as recognizable templates (QTemplate). */
class PeptidesStoreQuestions(model: Model) {
    val treatedTrialCandidates = QTemplate.of(model, "GreenhouseTrial", RefName("TreatedTrial"))
    val evaluatedTrialCandidates = QTemplate.of(model, "GreenhouseTrial", RefName("EvaluatedTrial"))
    val greenhouseValidatedCandidates = QTemplate.of(model, "Peptide", RefName("GreenhouseValidated"))
    val lockedObservationCandidates = QTemplate.of(model, "PlotObservation", RefName("LockedObservation"))
    val treatedPlotCandidates = QTemplate.of(model, "GreenhousePlot", RefName("TreatedPlot"))
    val activeTrialCandidates = QTemplate.of(model, "GreenhouseTrial", RefName("ActiveTrial"))
    val outOfBandCandidates = QTemplate.of(model, "Greenhouse", RefName("OutOfBand"))
    val openExcursionCandidates = QTemplate.of(model, "ClimateExcursion", RefName("OpenExcursion"))
    val permittedTrialCandidates = QTemplate.of(model, "FieldTrial", RefName("PermittedTrial"))
    val plantedTrialCandidates = QTemplate.of(model, "FieldTrial", RefName("PlantedTrial"))
    val harvestedTrialCandidates = QTemplate.of(model, "FieldTrial", RefName("HarvestedTrial"))
    val overdueTaskCandidates = QTemplate.of(model, "CollectionTask", RefName("OverdueTask"))
    val recordLabHitCandidates = QTemplate.of(model, "LabExperiment", model.rules.getValue("RecordLabHit").condition)
    val openClimateExcursionCandidates = QTemplate.of(model, "Greenhouse", model.rules.getValue("OpenClimateExcursion").condition)
    val raiseSensorAlertCandidates = QTemplate.of(model, "Greenhouse", model.rules.getValue("RaiseSensorAlert").condition)
    val noticeWashOffCandidates = QTemplate.of(model, "TreatmentApplication", model.rules.getValue("NoticeWashOff").condition)
    val noticeHaltCandidates = QTemplate.of(model, "FieldTrial", model.rules.getValue("NoticeHalt").condition)
    val remindTaskCandidates = QTemplate.of(model, "CollectionTask", model.rules.getValue("RemindTask").condition)
    val never1Candidates = QTemplate.of(model, "Peptide", model.nevers[0].target)
    val never2Candidates = QTemplate.of(model, "AssayReading", model.nevers[1].target)
    val never3Candidates = QTemplate.of(model, "AssayReading", model.nevers[2].target)
    val never4Candidates = QTemplate.of(model, "PlotObservation", model.nevers[3].target)
    val never5Candidates = QTemplate.of(model, "PlotObservation", model.nevers[4].target)
    val never6Candidates = QTemplate.of(model, "PlotObservation", model.nevers[5].target)
    val never9Candidates = QTemplate.of(model, "Scouting", model.nevers[8].target)
    val never10Candidates = QTemplate.of(model, "Scouting", model.nevers[9].target)
    val never11Candidates = QTemplate.of(model, "Harvest", model.nevers[10].target)
    val never12Candidates = QTemplate.of(model, "PhytotoxicityReport", model.nevers[11].target)
    val never14Candidates = QTemplate.of(model, "CollectionTask", model.nevers[13].target)
}

/**
 * PeptidesStore over any generic backend — a model-driven store or a framework.
 * Every method is implemented; override only the questions worth hand-tuning.
 */
open class PeptidesStoreOverGeneric(
    private val backend: StateResolver,
    model: Model,
) : PeptidesStore {
    private val questions = PeptidesStoreQuestions(model)

    override fun begin(kind: WorkKind): UnitOfWork = backend.begin(kind)

    override fun crops(keys: List<StoreKey>): List<CropRow> = backend.fetchByKeys("Crop", keys).map { it.toCropRow() }
